diff --git a/tests/cases/compiler/mappedTypeOverInlineTypeAssertionDisplay.ts b/tests/cases/compiler/mappedTypeOverInlineTypeAssertionDisplay.ts
new file mode 100644
index 000000000..2895b8346
--- /dev/null
+++ b/tests/cases/compiler/mappedTypeOverInlineTypeAssertionDisplay.ts
@@ -0,0 +1,38 @@
+// @strict: true
+// @declaration: true
+
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
+// Same thing with the assertion hoisted to a separate declaration (displays correctly).
+const strWrapper = stringWrapper() as Wrapper<"hello">
+const value2 = objWrapper({
+    prop1: strWrapper
+})
+type Test2 = Unwrap<typeof value2>
+
+// The underlying type is correct; only the printed form is wrong.
+type Test3 = Unwrap<typeof value>["prop1"]
+
+// Declaration emit inlines the printed type; it should be `{ prop1: "hello"; }`.
+export declare const test: Test;
+export const testInlined = test;
